/** Shape of `src/data/images.json`, generated by `scripts/optimize-images.ts`. */

export interface ManifestImage {
  /** "0", "1", ... or "reference" */
  name: string;
  /** Content hash, part of the file names so the files can be cached forever */
  hash: string;
  /** Dimensions of the largest variant */
  width: number;
  height: number;
  /** Widths of all generated variants, ascending */
  widths: number[];
  /** Dominant color, shown while the image loads */
  color: string;
}

export type ImageManifest = Record<string, ManifestImage[]>;
